17	 * If you need to wait X milliseconds between events A and B, but event B
18	 * doesn't happen exactly after event A, you record the timestamp (jiffies) of
19	 * when event A happened, then just before event B you call this function and
20	 * pass the timestamp as the first argument, and X as the second argument.
21	 */
22	static inline void
23	wait_remaining_ms_from_jiffies(unsigned long timestamp_jiffies, int to_wait_ms)
24	{
25		unsigned long target_jiffies, tmp_jiffies, remaining_jiffies;
26	
27		/*
28		 * Don't re-read the value of "jiffies" every time since it may change
29		 * behind our back and break the math.
30		 */
31		tmp_jiffies = jiffies;
32		target_jiffies = timestamp_jiffies +
33				 msecs_to_jiffies_timeout(to_wait_ms);
34	
35		if (time_after(target_jiffies, tmp_jiffies)) {
36			remaining_jiffies = target_jiffies - tmp_jiffies;
37			while (remaining_jiffies)
38				remaining_jiffies =
39				    schedule_timeout_uninterruptible(remaining_jiffies);
40		}
